from pathlib import Path
p=Path(__file__).resolve().parents[1]/'docs/guide.html';s=p.read_text(encoding='utf-8')
marker='<h3>프리팹 정의 간 연쇄·순환 참조</h3>'
addition='''<h3>물리 프리팹의 런타임 생성과 활성 상태</h3><p>기존 내보내기에서 지원하는 기본 충돌체·Rigidbody 구성의 런타임 프리팹 생성 경로를 추가했습니다. 실제 테스트는 동적 Box·Sphere, Kinematic Capsule, 비활성 Box 프리팹과 재활성화·삭제를 포함합니다. 충돌체 종류·크기·질량·중력·시뮬레이션 상태·속도와 프리팹/내부 객체 참조를 실행 및 재내보내기로 대조합니다.</p><p>Unreal의 장면별 프로토타입은 실제 물리 컴포넌트를 저장하지만 시뮬레이션은 정지합니다. 복제본은 자신의 활성 상태에 맞게 시뮬레이션을 시작하고, 비활성화할 때 속도를 보관해 재활성화 때 복원합니다. 프로토타입과 정의의 물리 속성을 각각 스냅샷으로 검사하므로 한쪽만 변경한 상태로 역변환하면 재가져오기를 요구합니다.</p><p>첫 실행에서는 Unreal이 Instantiate한 프레임부터 중력을 적용해 Unity보다 한 물리 단계 앞섰습니다. 변환 스크립트의 Update를 물리 처리 이후 단계로 옮겨 생성 프레임의 위상을 맞췄습니다. 서로 충돌하지 않는 무감쇠 자유낙하 테스트에는 위치 0.0001m, 속도 0.0001m/s 기준을 적용했습니다. 기존 지면 접촉·250프레임 검사의 별도 물리 해석 오차 기준은 유지하며, 두 엔진의 모든 물리 상황이 동일하다는 뜻은 아닙니다.</p><p>비활성 루트의 Rigidbody를 복합 충돌체로 잘못 판정한 내보내기 검사도 수정했습니다. 복합 충돌체·비지원 축/모드·임의 물리 API와 충돌 콜백, 물리와 애니메이션/UI를 함께 복제하는 모든 조합은 여전히 미지원 또는 미검증입니다. 런타임 애니메이션·UI 프리팹 실행 연결은 별도 구현 항목입니다.</p>'''
assert marker in s
if addition not in s:s=s.replace(marker,addition+marker)
s=s.replace('물리·애니메이션·UI·카메라·라이트·Volume을 포함한 런타임 프리팹은 이 지원 범위에 포함되지 않으며 사전 검사를 유지합니다.','물리 구성은 위 절의 검증 범위에서 추가 지원합니다. 애니메이션·UI·카메라·라이트·Volume을 포함한 런타임 프리팹은 사전 검사를 유지합니다.')
s=s.replace('런타임 프리팹의 일반 물리·애니메이션·UI 구성, 중첩·Variant 및 임의 API는 별도 미지원 범위입니다.','런타임 물리 프리팹은 위 절의 범위를 참고하십시오. 애니메이션·UI 구성, 중첩·Variant 및 임의 API는 별도 미지원 범위입니다.')
p.write_text(s,encoding='utf-8');print('RUNTIME_PHYSICS_PREFAB_GUIDE_UPDATED')
